$ErrorActionPreference='Stop'
$bsdfRepo=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path
$bsdfManifest=Join-Path $PSScriptRoot 'evidence-manifest.json'
if(Test-Path -LiteralPath $bsdfManifest){throw 'Already sealed. Use a new evidence directory.'}
& (Join-Path $PSScriptRoot 'verify-final.ps1')
$bsdfSummary=Get-Content (Join-Path $PSScriptRoot 'final-verification-summary.json') -Raw | ConvertFrom-Json
$bsdfDocs=@('docs/XYZ_LOG_RECONSTRUCTION_2026-11-01.md','docs/CURRENT_STATUS.md','docs/STAROPT_FILE_FORMAT.md','docs/FILE_FORMATS_AND_PLUGINS.md','docs/CAMERA_IMAGING_LAB.md','docs/NON_SEQUENTIAL_TRACING.md','docs/NONSEQUENTIAL_PHASE2_STRAY_LIGHT.md','docs/NONSEQUENTIAL_ZEMAX_PARITY_ROADMAP.md','docs/NUMERICAL_PARITY.md','docs/README.md','docs/XYZ_MEASURED_ANGULAR_2026-11-01.md','docs/XYZ_KNOWN_CONDITIONS_2026-11-01.md')
$bsdfFiles=@(Get-ChildItem -LiteralPath $PSScriptRoot -File -Recurse | Sort-Object FullName | ForEach-Object {[pscustomobject]@{Path=[IO.Path]::GetRelativePath($PSScriptRoot,$_.FullName).Replace('\','/');Bytes=$_.Length;Sha256=(Get-FileHash -LiteralPath $_.FullName).Hash.ToLowerInvariant()}})
[ordered]@{CapturedUtc=[DateTimeOffset]::UtcNow.ToString('o');Scope='Explicit log angular reconstruction, all eight Cornell measured incidences at 550 nm, measured normal-incidence BTDF, and bounded absolute XYZ transfer under declared derived conditions. Blue Acrylic calibration remains unqualified.';ProductTestsPassed=332;NewRemainingMaterialCalibrationsApproved=2;RemainingMaterialsRejected=1;Cornell550NanometerIncidencesPassive=40;MeasuredAngularChainsPassed=43;HistogramBins=1376;CalibratedSyntheticShapeChainsPassed=4;WhitePowerControlsPassed=23;FullCommercialCertification=$false;IndependentBlindValidation=$false;AllCornellSpectralBandsQualified=$false;MeasuredBackSideCertified=$false;DefaultReleaseAppBuildPassed=$true;PriorFrozenFilesVerified=1694;ExecutedCoreSha256=$bsdfSummary.CoreSha256;ExecutedApplicationSha256=$bsdfSummary.ApplicationSha256;ExecutionCopies='External task-owned FrozenReconstruction20261101 directory, nine critical binaries bound by before/after execution hashes and six PDB document checksum audits.';Excludes=@('evidence-manifest.json');DocumentationAtSeal=@($bsdfDocs | ForEach-Object {[pscustomobject]@{Path=$_;Sha256=(Get-FileHash -LiteralPath (Join-Path $bsdfRepo $_)).Hash.ToLowerInvariant()}});Files=$bsdfFiles} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $bsdfManifest -Encoding utf8
Write-Output "Sealed $($bsdfFiles.Count) evidence files."
